import axios from 'axios';

import { interceptor } from './interceptor';
import {
    BASE_URL,
    CREATE_BIN,
    CREATE_BIN_ERROR,
    GET_BIN,
    GET_BIN_ERROR,
    GET_BINS,
    GET_BINS_ERROR,
    GET_BINS_UNPAGINATED,
    GET_BINS_UNPAGINATED_ERROR,
    UPDATE_BIN,
    UPDATE_BIN_ERROR,
} from './types';


interceptor();

export const createBin = (values) => dispatch => {
    axios.post(`${BASE_URL}/bins`,values)
        .then((response)=>{
            dispatch({
                type:CREATE_BIN,
                payload:response
            })
        })
        .catch(err =>{
            dispatch({
                type:CREATE_BIN_ERROR,
                payload:err
            });
        })
}


export const fetchBins = () => dispatch => {
    axios({
        method:'GET',
        url:`${BASE_URL}/bins`
    }).then((response) =>{
        dispatch({
            type:GET_BINS_UNPAGINATED,
            payload:response
        })
    })
    .catch(err => {
        dispatch({
            type:GET_BINS_UNPAGINATED_ERROR,
            payload:err
        })
    })
}

export const fetchBinsPaginated = (page) => dispatch => {
    axios({
        method:'GET',
        url:`${BASE_URL}/bins?page=${page}&size=20`
    }).then((response) =>{
        dispatch({
            type:GET_BINS,
            payload:response.data
        })
    })
    .catch(err => {
        dispatch({
            type:GET_BINS_ERROR,
            payload:err
        })
    })
}

export const fetchBin =(id) => dispatch => {
    axios({
        method:'GET',
        url:`${BASE_URL}/bins/${id}`
    }).then(response => {
        dispatch({
            type:GET_BIN,
            payload:response.data
        })
    })
    .catch(err => {
        dispatch({
            type:GET_BIN_ERROR,
            payload:err
        })
    })
}

export const updateBin= (values) => dispatch => {
    let {id} = values
    axios.put(`${BASE_URL}/bins/${id}`,values)
        .then((response) => {
            dispatch({
                type:UPDATE_BIN,
                payload:response
            })
        })
        .catch(err => {
            dispatch({
                type:UPDATE_BIN_ERROR,
                payload:err
            })
        })
}
